import mongoose, { Schema } from 'mongoose';
import { v4 as uuidv4 } from 'uuid';

export interface IMediaAsset {
  _id: string;
  /** Name generated by the server; the uploader's filename is never used on disk. */
  storedName: string;
  originalName: string;
  mimeType: string;
  size: number;
  kind: 'image' | 'document';
  altText?: string;
  /** Public assets are served to anyone; private ones only to signed-in staff. */
  visibility: 'public' | 'private';
  uploadedBy?: string;
  isDeleted: boolean;
  createdAt: Date;
  updatedAt: Date;
}

// Metadata only. The file itself lives on disk (or an object store) outside the web root and is
// never stored in MongoDB documents.
const mediaAssetSchema = new Schema<IMediaAsset>(
  {
    _id: { type: String, default: () => uuidv4() },
    storedName: { type: String, required: true, unique: true },
    originalName: { type: String, required: true, maxlength: 200 },
    mimeType: { type: String, required: true, maxlength: 100 },
    size: { type: Number, required: true, min: 1 },
    kind: { type: String, enum: ['image', 'document'], required: true },
    altText: { type: String, trim: true, maxlength: 200 },
    visibility: { type: String, enum: ['public', 'private'], default: 'public' },
    uploadedBy: { type: String },
    isDeleted: { type: Boolean, default: false },
  },
  { timestamps: true, _id: false },
);

mediaAssetSchema.index({ kind: 1, createdAt: -1 });

export default mongoose.model<IMediaAsset>('MediaAsset', mediaAssetSchema);
